package dev.jay.usbdirect

import org.json.JSONArray
import org.json.JSONObject

/** A named user preset (built-ins are generated by [DspPresets]). */
data class EqPreset(val name: String, val config: DspConfig)

/** JSON helpers shared by prefs, backup and user presets. */
object DspJson {

    fun bandToJson(b: DspBand): JSONObject = JSONObject().apply {
        put("type", b.type)
        put("fc", b.fc)
        put("q", b.q)
        put("gain", b.gainDb)
        put("enabled", b.enabled)
    }

    fun bandFromJson(o: JSONObject): DspBand? {
        if (!o.has("fc") || !o.has("q")) return null
        return DspBand(
            type = o.optInt("type", 0),
            fc = o.optDouble("fc", 1000.0),
            q = o.optDouble("q", 0.707),
            gainDb = o.optDouble("gain", 0.0),
            enabled = o.optBoolean("enabled", true)
        )
    }

    fun bandsToJson(bands: List<DspBand>): JSONArray {
        val arr = JSONArray()
        for (b in bands.take(12)) arr.put(bandToJson(b))
        return arr
    }

    fun bandsFromJson(text: String?): List<DspBand> {
        if (text.isNullOrBlank()) return emptyList()
        return runCatching {
            val arr = JSONArray(text)
            (0 until arr.length()).mapNotNull { i ->
                arr.optJSONObject(i)?.let(::bandFromJson)
            }
        }.getOrDefault(emptyList())
    }

    fun configToJson(config: DspConfig): JSONObject = JSONObject().apply {
        put("preampDb", config.preampDb)
        put("autoHeadroom", config.autoHeadroom)
        put("bands", bandsToJson(config.bands))
    }

    fun configFromJson(o: JSONObject?): DspConfig {
        if (o == null) return DspConfig()
        val bandsArr = o.optJSONArray("bands")
        val bands = if (bandsArr != null) {
            (0 until bandsArr.length()).mapNotNull { i ->
                bandsArr.optJSONObject(i)?.let(::bandFromJson)
            }
        } else emptyList()
        return DspConfig(
            bands = bands,
            preampDb = o.optDouble("preampDb", 0.0),
            autoHeadroom = o.optBoolean("autoHeadroom", true)
        )
    }

    fun presetToJson(p: EqPreset): JSONObject = JSONObject().apply {
        put("name", p.name)
        put("config", configToJson(p.config))
    }

    fun presetFromJson(o: JSONObject?): EqPreset? {
        if (o == null) return null
        val name = o.optString("name").trim()
        if (name.isEmpty()) return null
        return EqPreset(name, configFromJson(o.optJSONObject("config")))
    }

    fun presetsToJson(presets: List<EqPreset>): JSONArray {
        val arr = JSONArray()
        for (p in presets) arr.put(presetToJson(p))
        return arr
    }

    fun presetsFromJson(text: String?): List<EqPreset> {
        if (text.isNullOrBlank()) return emptyList()
        return runCatching {
            val arr = JSONArray(text)
            (0 until arr.length()).mapNotNull { i ->
                presetFromJson(arr.optJSONObject(i))
            }
        }.getOrDefault(emptyList())
    }
}

/** Factory presets; keep them small and musically useful. */
object DspPresets {

    val Flat = DspConfig()

    val builtin: List<Pair<String, DspConfig>> = listOf(
        "Flat" to Flat,
        "Bass boost" to DspConfig(
            bands = listOf(
                DspBand(type = 1, fc = 100.0, q = 0.70, gainDb = 6.0)
            ),
            preampDb = -2.0,
            autoHeadroom = true
        ),
        "Treble boost" to DspConfig(
            bands = listOf(
                DspBand(type = 2, fc = 7500.0, q = 0.70, gainDb = 5.0)
            ),
            preampDb = -2.0,
            autoHeadroom = true
        ),
        "Vocal" to DspConfig(
            bands = listOf(
                DspBand(type = 0, fc = 250.0, q = 1.00, gainDb = -2.0),
                DspBand(type = 0, fc = 2500.0, q = 1.20, gainDb = 3.0)
            ),
            preampDb = -1.0,
            autoHeadroom = true
        )
    )

    fun find(name: String): DspConfig? =
        builtin.firstOrNull { it.first == name }?.second
}
